// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Math AI focuses on real-world modeling and using technology. Let's start with numbers and money.","blocks":[{"t":"key","text":"Scientific notation a × 10ᵏ (1 ≤ a < 10). Round to significant figures or decimal places as asked. Percentage error = |approximate − exact|/|exact| × 100%."},{"t":"p","text":"Financial math: compound interest FV = PV(1 + r/(100k))^(kn). Use the GDC's finance solver (TVM) for loans, savings and annuities. Depreciation reduces value by a percentage each year."},{"t":"ex","problem":"A car worth $20,000 depreciates 15% per year. Find its value after 3 years.","steps":["20,000 × 0.85³"],"answer":"about $12,282.50"},{"t":"p","text":"Inflation reduces purchasing power; real interest rates account for it."}]},{"say":"Sequences model patterns of growth in savings, populations and more.","blocks":[{"t":"key","text":"Arithmetic sequences model linear growth: uₙ = u₁ + (n − 1)d. Geometric sequences model exponential growth: uₙ = u₁rⁿ⁻¹."},{"t":"p","text":"Use sums to find totals: Sₙ = (n/2)(2u₁ + (n − 1)d) for arithmetic; Sₙ = u₁(rⁿ − 1)/(r − 1) for geometric."},{"t":"ex","problem":"A gym membership costs $30 the first month and rises by $2 each month. What's the total for a year?","steps":["Arithmetic: u₁ = 30, d = 2, n = 12"],"answer":"S₁₂ = 6(60 + 22) = $492"},{"t":"p","text":"Real-world data rarely fits perfectly; Math AI emphasizes choosing an appropriate model and judging its limitations."}]}],[{"say":"Math AI is all about choosing a function that models real data and interpreting its parameters.","blocks":[{"t":"key","text":"Linear model f(x) = mx + c: constant rate of change m. Quadratic model f(x) = ax² + bx + c: models projectiles and areas, with the vertex as the maximum or minimum."},{"t":"p","text":"Use the GDC to find intersections, zeros, maxima and minima, and to fit regression models to data."},{"t":"ex","problem":"A ball's height is h(t) = −4.9t² + 20t + 1.5. Find the maximum height.","steps":["Vertex at t = −20/(2 × −4.9) ≈ 2.04 s"],"answer":"h ≈ 21.9 m"},{"t":"p","text":"Interpret parameters in context: in C = 15n + 200, 15 is the cost per item and 200 is a fixed cost."}]},{"say":"Different situations need different models. Choosing the right one is a key AI skill.","blocks":[{"t":"key","text":"Exponential f(x) = ka⁽ˣ⁾ + c models growth and decay (populations, cooling, radioactivity). Sinusoidal f(x) = a sin(b(x − c)) + d models periodic data (tides, temperatures)."},{"t":"p","text":"Other models: direct and inverse variation, cubic models, and logistic models for growth with a limit (HL)."},{"t":"p","text":"Choose a model by examining the data pattern, context and residuals. Use the coefficient of determination R² to judge fit (closer to 1 is better)."},{"t":"ex","problem":"Daylight hours peak at 15 in June and bottom at 9 in December. Find the amplitude and principal axis.","steps":["Amplitude = (15 − 9)/2 = 3"],"answer":"Principal axis y = 12"}]}],[{"say":"Geometry in Math AI solves real measurement problems: heights, distances, areas and volumes.","blocks":[{"t":"key","text":"Right triangles: SOH-CAH-TOA and Pythagoras. Non-right triangles: sine rule, cosine rule and area = ½ab sin C. Angles of elevation and depression and bearings appear in many problems."},{"t":"p","text":"3D: volume and surface area of prisms, cylinders, cones, pyramids and spheres; find lengths and angles inside 3D shapes using right triangles."},{"t":"ex","problem":"From 50 m away, the angle of elevation to a building's top is 32°. Find its height.","steps":["tan 32° = h/50"],"answer":"h = 50 tan 32° ≈ 31.2 m"}]},{"say":"Voronoi diagrams solve location problems, like finding the nearest hospital. They're unique to Math AI.","blocks":[{"t":"key","text":"A Voronoi diagram divides a region into cells around sites (points) so every location in a cell is closer to its site than any other."},{"t":"list","items":["Cell edges lie on perpendicular bisectors between neighboring sites.","Vertices are equidistant from three or more sites.","The \"toxic waste dump\" problem: find the point farthest from all sites (often at a vertex of the diagram)."]},{"t":"p","text":"Applications: placing new stores or emergency services, mapping cell phone towers."},{"t":"ex","problem":"Two sites are at (0, 0) and (6, 0). Where is the boundary between their cells?","steps":["The perpendicular bisector of the segment"],"answer":"The vertical line x = 3"}]}],[{"say":"Math AI emphasizes statistics heavily. You'll collect, analyze and interpret real data.","blocks":[{"t":"key","text":"Sampling methods (simple random, systematic, stratified, quota, convenience) and possible bias. Descriptive statistics: mean, median, quartiles, standard deviation, box plots and cumulative frequency graphs."},{"t":"p","text":"Bivariate data: Pearson's r for linear correlation; Spearman's rank correlation for monotonic relationships. The regression line of y on x predicts y."},{"t":"ex","problem":"Spearman's rank coefficient is 0.9 for two judges' rankings. Interpret.","steps":["Strong positive association between the rankings"],"answer":"The judges largely agree"},{"t":"p","text":"Correlation never proves causation."}]},{"say":"Math AI uses probability distributions and hypothesis tests to make decisions from data.","blocks":[{"t":"key","text":"Probability rules, Venn and tree diagrams, conditional probability. Distributions: binomial B(n, p) and normal N(μ, σ²), computed with the GDC."},{"t":"p","text":"Chi-squared tests: test for independence (contingency tables) and goodness of fit. State H₀ and H₁, find the p-value, and compare with the significance level: if p < α, reject H₀."},{"t":"p","text":"The t-test compares means (SL: two-sample t-test)."},{"t":"p","text":"Internal assessment: the mathematical exploration often uses real data and statistics, and it's worth 20% of the grade."},{"t":"ex","problem":"A chi-squared test for independence gives p = 0.02 at the 5% level. Conclusion?","steps":["0.02 < 0.05"],"answer":"Reject H₀: there is evidence the variables are dependent"}]}],[{"say":"Calculus in Math AI focuses on rates of change and optimizing real situations.","blocks":[{"t":"key","text":"The derivative gives the rate of change and the gradient of the tangent. Power rule: d/dx (axⁿ) = naxⁿ⁻¹."},{"t":"p","text":"Stationary points occur where f′(x) = 0; use them to find maximum profit, minimum cost or maximum area. Use the GDC to verify."},{"t":"ex","problem":"Profit P(x) = −2x² + 80x − 300. Find the number of units that maximizes profit.","steps":["P′(x) = −4x + 80 = 0"],"answer":"x = 20 units (maximum profit $500)"},{"t":"p","text":"HL adds more differentiation rules, related rates and differential equations (including slope fields and Euler's method)."}]},{"say":"Integration finds accumulated totals and areas. When there's no formula, the trapezoidal rule estimates them.","blocks":[{"t":"key","text":"∫ axⁿ dx = axⁿ⁺¹/(n + 1) + C. Definite integrals give the area under a curve (use the GDC to evaluate)."},{"t":"p","text":"The trapezoidal rule estimates area with trapezoids: A ≈ (h/2)[y₀ + yₙ + 2(y₁ + … + yₙ₋₁)], where h is the strip width. It's useful when you only have data points."},{"t":"ex","problem":"Estimate the area under a curve with y-values 2, 4, 5 at x = 0, 1, 2.","steps":["h = 1","(1/2)[2 + 5 + 2(4)]"],"answer":"7.5 square units"}]}]];
export default text;
